```
import numpy as np

def weight_subgraph(G, k):
    # Create a data structure to represent the graph G
    adj_list = {}
    for vertex in G:
        adj_list[vertex] = []
        for neighbor in G[vertex]:
            adj_list[vertex].append(neighbor)

    # Build up a table of weights for all possible subgraphs
    weights = np.zeros((len(G), len(G), k+1))
    for i in range(len(G)):
        for j in range(i+1, len(G)):
            for w in range(k+1):
                weights[i, j, w] = float('inf')
                for vertex in G:
                    if vertex in G[i]:
                        for neighbor in G[vertex]:
                            if neighbor in G[j]:
                                weights[i, j, w] = min(weights[i, j, w], weights[i, vertex, w-weights[vertex]] + weights[vertex, neighbor, w-weights[neighbor]])

    # Search for a subgraph of weight k
    for i in range(len(G)):
        for j in range(i+1, len(G)):
            if weights[i, j, k]!= float('inf'):
                return True

    return False
